package pl.zagranietyper.parser;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class FootballPeriodStatisticSyntaxAdapterTest {private final FootballPeriodStatisticSyntaxAdapter p=new FootballPeriodStatisticSyntaxAdapter();@Test void parsesWholeTeamCornerPeriodMarkets(){assertTrue(p.parse("Brighton +1.5 rzutów rożnych w każdej połowie","Newcastle","Brighton").parsed());assertTrue(p.parse("Bayern +2.5 rzutów rożnych w 1. połowie","Inter","Bayern München").parsed());}@Test void rejectsUnsafeForms(){assertFalse(p.parse("Anglia +2.5 rzutów rożnych w 1. połowie","Finland","England").parsed());assertFalse(p.parse("1. połowa – Getafe powyżej 0.5 kartki","Barcelona","Getafe").parsed());assertFalse(p.parse("Kane +1.5 strzałów w 1. połowie","Tottenham","Arsenal").parsed());assertFalse(p.parse("Tottenham +1.5 rożnych w 1. połowie i wygra","Tottenham","Arsenal").parsed());}}
